/**
 * Creates an admin user for FOOTBALL DRAFT ADMIN.
 *
 *   npm run admin:create:local -- --username alice [--role owner] [--no-totp]
 *   npx tsx scripts/create-admin.ts --env staging --username alice [--totp-on-first-login]
 *
 * The password is read from FD_ADMIN_PASSWORD (or prompted).
 * A TOTP secret is generated by default; register the printed otpauth URI in
 * an authenticator app. --no-totp is only allowed with --local.
 * --totp-on-first-login prints no secret: in environments that require 2FA the
 * admin registers an authenticator app at the first login in the admin site
 * (used by the GitHub Actions workflow, so no key appears in CI logs).
 */
import { execFileSync } from 'node:child_process';
import { createInterface } from 'node:readline/promises';
import { base32Encode, hashPassword, randomBytes, randomId } from '../src/lib/crypto';

const args = process.argv.slice(2);
const flag = (name: string) => args.includes(`--${name}`);
const opt = (name: string) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 ? args[i + 1] : undefined;
};

async function main() {
  const local = flag('local');
  const env = opt('env');
  if (!local && !env) throw new Error('use --local or --env <dev|staging|production>');
  const username = opt('username');
  if (!username || !/^[a-zA-Z0-9_.-]{3,40}$/.test(username)) throw new Error('--username is required (3-40 chars)');
  const role = opt('role') ?? 'owner';
  if (!['owner', 'admin', 'viewer'].includes(role)) throw new Error('--role must be owner, admin or viewer');
  const noTotp = flag('no-totp');
  if (noTotp && !local) throw new Error('--no-totp is only allowed for --local');
  const totpLater = flag('totp-on-first-login');

  let password = process.env.FD_ADMIN_PASSWORD ?? '';
  if (!password) {
    const rl = createInterface({ input: process.stdin, output: process.stdout });
    password = await rl.question('password (min 12 chars): ');
    rl.close();
  }
  if (password.length < 12) throw new Error('password must be at least 12 characters');

  const { hash, salt, iterations } = await hashPassword(password);
  const totpSecret = noTotp || totpLater ? null : base32Encode(randomBytes(20));
  const now = Date.now();
  const q = (v: string | number | null) => (v === null ? 'NULL' : typeof v === 'number' ? String(v) : `'${v.replace(/'/g, "''")}'`);
  const sql = `INSERT INTO admin_users (id, username, password_hash, password_salt, password_iterations, role, totp_secret, totp_enabled, status, created_at, updated_at) VALUES (${[
    randomId(),
    username,
    hash,
    salt,
    iterations,
    role,
    totpSecret,
    totpSecret ? 1 : 0,
    'active',
    now,
    now,
  ]
    .map(q)
    .join(',')});`;
  const wranglerArgs = ['wrangler', 'd1', 'execute', 'DB', '--command', sql, ...(local ? ['--local'] : ['--remote', '--env', env as string])];
  execFileSync('npx', wranglerArgs, { stdio: ['ignore', 'ignore', 'inherit'] });
  console.log(`admin "${username}" (${role}) created${local ? ' in the local database' : ` in ${env}`}.`);
  if (totpLater) console.log('2FA: register an authenticator app at the first login in the admin site.');
  if (totpSecret) {
    console.log('\nTOTP secret (register in an authenticator app):');
    console.log(`  ${totpSecret}`);
    console.log(`  otpauth://totp/FOOTBALL%20DRAFT%20ADMIN:${encodeURIComponent(username)}?secret=${totpSecret}&issuer=FOOTBALL%20DRAFT%20ADMIN`);
  }
}

main().catch((e) => {
  console.error(String(e instanceof Error ? e.message : e));
  process.exit(1);
});
